    /* Unsupported compression type */
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "UnsupportedPSDCompression", "`%s' (channel %zu)", psd_info->filename, channel);
    return MagickFalse;
  }

  /* Allocate sizes for mask */
  sizes = (size_t *) AcquireQuantumMemory(image->columns, sizeof(*sizes));
  if (sizes == (size_t *) NULL)
  {
    (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError, "UnableToAcquireMemory", "`%s'", image_info->filename);
    return MagickFalse;
  }

  /* Process mask if applicable */
  if (layer_info->has_mask)
  {
    count = 0;
    /* Placeholder for actual mask handling logic */
    (void) count;
  }

  /* Seek back to the position after the channel data */
  if (SeekBlob(image, psd_info->channel_data_offset[channel], SEEK_SET) == -1)
  {
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError, "UnableToSeekPSDChannelData", "`%s'", image_info->filename);
    status = MagickFalse;
  }

  /* Clean up allocated resources */
  if (sizes != (size_t *) NULL)
    sizes = (size_t *) RelinquishMagickMemory(sizes);

  return status;
